//! Fixed-point integer quantities used by strategies.

#[cfg(feature = "verus")]
use vstd::prelude::*;

/// A quantity in thousandths (milli-units).
#[cfg_attr(feature = "verus", verus_verify)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Milli(pub u32);

/// Gun heat generated by firing: `1 + power / 5`, in milli-units.
#[cfg_attr(feature = "verus", verus_verify)]
#[cfg_attr(feature = "verus", verus_spec(r =>
    requires power.0 <= 3000,
    ensures r.0 >= 1000 && r.0 <= 1600
))]
pub fn gun_heat_for_power(power: Milli) -> Milli {
    Milli(1000 + power.0 / 5)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn gun_heat_for_max_power() {
        assert_eq!(gun_heat_for_power(Milli(3000)), Milli(1600));
    }
}
